package com.nimbusbill.customer.dto;
import com.nimbusbill.customer.entity.PricingUnit; import com.nimbusbill.customer.entity.ProductStatus; import jakarta.validation.constraints.*; import java.math.BigDecimal; import java.time.LocalDate; import java.util.Set;
public record ProductRequest(@NotBlank @Size(max=30) @Pattern(regexp="^[A-Z0-9_-]+$") String productCode,@NotBlank @Size(max=120) String productName,@Size(max=500) String description,@NotNull PricingUnit pricingUnit,@DecimalMin("0.0") BigDecimal minimumFee,@DecimalMin("0.0") BigDecimal maximumFee,boolean taxApplicable,@NotNull ProductStatus status,@NotNull LocalDate effectiveFrom,LocalDate effectiveTo,Set<@Pattern(regexp="^[A-Z0-9_-]+$") String> transactionTypes,Set<@Pattern(regexp="^[A-Z]{3}$") String> currencies){public ProductRequest(String productCode,String productName,String description,PricingUnit pricingUnit,BigDecimal minimumFee,BigDecimal maximumFee,boolean taxApplicable,ProductStatus status,LocalDate effectiveFrom,LocalDate effectiveTo){this(productCode,productName,description,pricingUnit,minimumFee,maximumFee,taxApplicable,status,effectiveFrom,effectiveTo,Set.of(productCode),Set.of("INR"));}}
